import{_ as l,o as i,c as e,a2 as r}from"./chunks/framework.D5wUhsuj.js";const p=JSON.parse('{"title":"首次登录","description":"","frontmatter":{},"headers":[],"relativePath":"quick-start/login.md","filePath":"quick-start/login.md"}'),t={name:"quick-start/login.md"};function o(h,a,n,s,d,c){return i(),e("div",null,[...a[0]||(a[0]=[r('<h1 id="首次登录" tabindex="-1">首次登录 <a class="header-anchor" href="#首次登录" aria-label="Permalink to &quot;首次登录&quot;">​</a></h1><h2 id="登录方式" tabindex="-1">登录方式 <a class="header-anchor" href="#登录方式" aria-label="Permalink to &quot;登录方式&quot;">​</a></h2><p>CipherGate 提供两种登录入口：</p><h3 id="_1-开发者登录" tabindex="-1">1. 开发者登录 <a class="header-anchor" href="#_1-开发者登录" aria-label="Permalink to &quot;1. 开发者登录&quot;">​</a></h3><p>适用于应用创建者和管理者。</p><h4 id="登录步骤" tabindex="-1">登录步骤 <a class="header-anchor" href="#登录步骤" aria-label="Permalink to &quot;登录步骤&quot;">​</a></h4><ol><li><p><strong>访问首页</strong></p><ul><li>打开平台首页</li><li>点击右上角「登录」按钮</li></ul></li><li><p><strong>输入账号信息</strong></p><ul><li>邮箱：注册时使用的邮箱</li><li>密码：设置的登录密码</li></ul></li><li><p><strong>完成登录</strong></p><ul><li>点击「登录」按钮</li><li>进入开发者后台</li></ul></li></ol><div class="warning custom-block"><p class="custom-block-title">注意</p><p>开发者账号需要管理员审批才能使用完整功能</p></div><h3 id="_2-应用用户登录" tabindex="-1">2. 应用用户登录 <a class="header-anchor" href="#_2-应用用户登录" aria-label="Permalink to &quot;2. 应用用户登录&quot;">​</a></h3><p>适用于被授权的终端用户。</p><h4 id="登录步骤-1" tabindex="-1">登录步骤 <a class="header-anchor" href="#登录步骤-1" aria-label="Permalink to &quot;登录步骤&quot;">​</a></h4><ol><li><p><strong>访问首页</strong></p><ul><li>打开平台首页</li><li>点击「应用用户登录」按钮</li></ul></li><li><p><strong>选择应用</strong></p><ul><li>如果有多个应用，选择要登录的应用</li><li>点击应用卡片进入登录</li></ul></li><li><p><strong>输入账号信息</strong></p><ul><li>邮箱：注册时使用的邮箱</li><li>密码：设置的登录密码</li><li>验证码：输入图形验证码</li></ul></li><li><p><strong>完成登录</strong></p><ul><li>点击「登录」按钮</li><li>进入应用用户中心</li></ul></li></ol><h2 id="登录后功能" tabindex="-1">登录后功能 <a class="header-anchor" href="#登录后功能" aria-label="Permalink to &quot;登录后功能&quot;">​</a></h2><h3 id="开发者后台" tabindex="-1">开发者后台 <a class="header-anchor" href="#开发者后台" aria-label="Permalink to &quot;开发者后台&quot;">​</a></h3><ul><li><a href="/docs/developer/">仪表盘</a> - 查看应用概览数据</li><li><a href="/docs/developer/application.html">应用管理</a> - 管理应用配置</li><li><a href="/docs/developer/app-user.html">用户管理</a> - 管理终端用户</li></ul><h3 id="应用用户中心" tabindex="-1">应用用户中心 <a class="header-anchor" href="#应用用户中心" aria-label="Permalink to &quot;应用用户中心&quot;">​</a></h3><ul><li><a href="/docs/portal/">仪表盘</a> - 查看个人数据</li><li><a href="/docs/portal/membership.html">会员信息</a> - 查看会员状态</li><li><a href="/docs/portal/recharge.html">充值</a> - 会员充值</li></ul><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><h3 id="q-忘记密码怎么办" tabindex="-1">Q: 忘记密码怎么办？ <a class="header-anchor" href="#q-忘记密码怎么办" aria-label="Permalink to &quot;Q: 忘记密码怎么办？&quot;">​</a></h3><p>A: 点击登录页面的「忘记密码」链接，通过邮箱重置密码。</p><h3 id="q-登录提示账号不存在" tabindex="-1">Q: 登录提示账号不存在？ <a class="header-anchor" href="#q-登录提示账号不存在" aria-label="Permalink to &quot;Q: 登录提示账号不存在？&quot;">​</a></h3><p>A: 请确认邮箱输入正确，或联系管理员确认账号状态。</p><h3 id="q-收到封禁提示" tabindex="-1">Q: 收到封禁提示？ <a class="header-anchor" href="#q-收到封禁提示" aria-label="Permalink to &quot;Q: 收到封禁提示？&quot;">​</a></h3><p>A: 联系应用管理员了解封禁原因并申请解封。</p>',24)])])}const q=l(t,[["render",o]]);export{p as __pageData,q as default};
